// MineBench: a choo-choo train — steam locomotive, tender, 2 passenger cars, station, trees, smoke

function ellipsoid(cx,cy,cz,rx,ry,rz,t){
  for(let x=-rx;x<=rx;x++) for(let y=-ry;y<=ry;y++) for(let z=-rz;z<=rz;z++){
    const v=x*x/(rx*rx)+y*y/(ry*ry)+z*z/(rz*rz);
    if(v<=1) block(cx+x,cy+y,cz+z,t);
  }
}
function cylinder(cx,cy,cz,r,h,t,axis){
  if(axis==='y') for(let y=0;y<h;y++) ellipsoid(cx,cy+y,cz,r,1,r,t);
  else if(axis==='x') for(let y=0;y<h;y++) ellipsoid(cx+y,cy,cz,r,1,r,t);
  else for(let y=0;y<h;y++) ellipsoid(cx,cy,cz+y,r,1,r,t);
}
function cone(cx,cy,cz,rH,rB,h,t){
  for(let y=0;y<h;y++){
    const f=y/h,cr=rB+(rH-rB)*f;
    if(cr>0.4) ellipsoid(cx,cy+y,cz,Math.max(0.5,cr),1,Math.max(0.5,cr),t);
  }
}
function dome(cx,cy,cz,r,t){
  for(let y=0;y<=r;y++) ellipsoid(cx,cy+y,cz,r,Math.max(0.5,Math.sqrt(Math.max(0,1-y*y/(r*r)))*r),r,t);
}
function track(x1,x2,z,t){
  for(let x=x1;x<=x2;x++){box(x,0,z-1,x,0,z+1,t);}
}

